// B-9 Parte 3: reintento del Selector cuando la busqueda quedo VACIA.
// Contador con $runIndex (n8n, por nodo — no un flag del sobre que se desincronice):
// 1a pasada por aca reintenta; 2a se rinde. Espejo de 'Prompt Reintento' del compositor.
const base = $('Prompt Selector').first().json;

let intento = 1;
try { intento = Number($runIndex) + 1; } catch (e) { intento = 1; }
if (!Number.isFinite(intento) || intento < 1) intento = 1;
const puedeReintentarBusqueda = intento < 2;

// que se busco y no trajo nada (para darle contexto util al Selector)
let terminos = '';
try { terminos = String($('Extraer Palabras').first().json.palabras || '').trim(); } catch (e) {}

return [{ json: {
  ...base,
  intentoBusqueda: intento,
  puedeReintentarBusqueda,
  // en la 2a vuelta ya no importa el prompt (va a mail); se deja el base intacto.
  promptAgente: puedeReintentarBusqueda ? [
    String(base.promptAgente || ''),
    '',
    '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
    'SEGUNDO INTENTO — TU BUSQUEDA ANTERIOR NO TRAJO NINGUN CANDIDATO.',
    '',
    terminos ? ('Buscaste con estos terminos y el catalogo no devolvio nada: ' + terminos)
             : 'La busqueda anterior no devolvio nada.',
    '',
    'Reinterpreta lo que pidio el cliente o ensancha la busqueda:',
    '  - Pudo usar una palabra coloquial que en el catalogo se llama distinto',
    '    (ej: "apuntes"/"fotocopias" -> "impresiones"; "carpeta" -> "anillado").',
    '  - Proba con un termino mas general o con sinonimos.',
    '  - Si nombro un producto que no existe tal cual, elegi el mas parecido.',
    'Es tu ultima vuelta: si esta busqueda tampoco trae nada, el cliente va a un mail.',
  ].join('\n') : String(base.promptAgente || ''),
} }];
